import{_ as l,C as s,o as e,c as i,a2 as a,b as n,w as r,a as d,E as g,a3 as c}from"./chunks/framework.CZGNF-7T.js";const D=JSON.parse('{"title":"회의 관리 (Meetings)","description":"","frontmatter":{},"headers":[],"relativePath":"work-manage/meeting.md","filePath":"work-manage/meeting.md","lastUpdated":1788446064000}'),E={name:"work-manage/meeting.md"};function u(h,o,C,m,B,_){const t=s("Mermaid");return e(),i("div",null,[o[1]||(o[1]=a('<h1 id="회의-관리-meetings" tabindex="-1">회의 관리 (Meetings) <a class="header-anchor" href="#회의-관리-meetings" aria-label="Permalink to &quot;회의 관리 (Meetings)&quot;">​</a></h1><blockquote><p><strong>IBS 회의 관리 모듈</strong>은 워크스페이스(본사 관리, 부동산 개발 프로젝트 등) 내에서 진행되는 모든 회의의 의사결정을 자산화하고, 논의된 결정 사항과 후속 조치를 <strong>실제 실무 업무(Issue/Task)로 직접 연결하여 추적</strong>하는 통합 의사결정 플랫폼입니다.</p></blockquote><h2 id="_1-개요-및-의사결정-자산화-파이프라인" tabindex="-1">1. 개요 및 의사결정 자산화 파이프라인 <a class="header-anchor" href="#_1-개요-및-의사결정-자산화-파이프라인" aria-label="Permalink to &quot;1. 개요 및 의사결정 자산화 파이프라인&quot;">​</a></h2><p>시스템 내의 모든 회의록은 특정 <strong>워크스페이스</strong>에 반드시 소속되어 관리됩니다. 회의에서 도출된 액션 아이템은 개별 업무(Issue)로 즉시 발행되어 완료율이 실시간으로 모니터링됩니다.</p>',4)),(e(),n(c,null,{default:r(()=>[g(t,{id:"mermaid-14",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%221.%20%ED%9A%8C%EC%9D%98%20%EC%82%AC%EC%A0%84%20%EC%A4%80%EB%B9%84%3Cbr%3E%EC%9D%98%EC%A0%9C%C2%B7%EC%B0%B8%EC%84%9D%EC%9E%90%20%EB%93%B1%EB%A1%9D%22%5D%20--%3E%20B%5B%222.%20%ED%9A%8C%EC%9D%98%20%EC%A7%84%ED%96%89%20%26%20%EA%B8%B0%EB%A1%9D%3Cbr%3E%EB%82%B4%EC%9A%A9%C2%B7%EA%B2%B0%EC%A0%95%EC%82%AC%ED%95%AD%C2%B7%ED%9B%84%EC%86%8D%EC%A1%B0%EC%B9%98%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%223.%20%EC%95%A1%EC%85%98%EC%95%84%EC%9D%B4%ED%85%9C%20%EC%97%B0%EB%8F%99%3Cbr%3E%EC%97%85%EB%AC%B4(Issue)%20%EB%B0%9C%ED%96%89%20%26%20%EB%B0%B0%EC%A0%95%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%224.%20%EC%A7%84%EC%B2%99%EB%8F%84%20%EC%8B%A4%EC%8B%9C%EA%B0%84%20%EC%B6%94%EC%A0%81%3Cbr%3E%EC%99%84%EB%A3%8C%EC%9C%A8%20%ED%94%84%EB%A1%9C%EA%B7%B8%EB%A0%88%EC%8A%A4%20%EB%B0%94%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%225.%20%ED%9A%8C%EC%9D%98%EB%A1%9D%20%EA%B3%B5%EC%8B%9D%20%ED%99%95%EC%A0%95%3Cbr%3EPDF%20%EB%B3%B4%EA%B4%80%20%26%20%ED%99%9C%EB%8F%99%20%EB%A1%9C%EA%B7%B8%22%5D%0A"})]),fallback:r(()=>[...o[0]||(o[0]=[d(" Loading... ",-1)])]),_:1})),o[2]||(o[2]=a('<h3 id="_1-1-기본-접근-및-권한" tabindex="-1">1.1 기본 접근 및 권한 <a class="header-anchor" href="#_1-1-기본-접근-및-권한" aria-label="Permalink to &quot;1.1 기본 접근 및 권한&quot;">​</a></h3><ul><li><strong>회의 목록 접근</strong>: 특정 워크스페이스 내부의 <code>[회의]</code> 탭 또는 상단 통합 메뉴의 <code>[회의]</code>를 통해 접근할 수 있습니다.</li><li><strong>회의 생성 권한</strong>: 워크스페이스 관리자(<code>workManager</code>) 또는 해당 워크스페이스의 참여 멤버에게 부여됩니다.</li><li><strong>잠금보관 워크스페이스 제약</strong>: 상태가 &#39;잠금보관(종료)&#39;인 워크스페이스는 신규 회의록 생성이 제한되며 기존 기록 조회만 가능합니다.</li></ul><h2 id="_2-회의록-목록-및-다차원-검색" tabindex="-1">2. 회의록 목록 및 다차원 검색 <a class="header-anchor" href="#_2-회의록-목록-및-다차원-검색" aria-label="Permalink to &quot;2. 회의록 목록 및 다차원 검색&quot;">​</a></h2><p>전체 회의 히스토리를 테이블 형태로 조회하고, 우측 사이드바 필터를 통해 원하는 회의록을 신속하게 검색할 수 있습니다.</p><h3 id="_2-1-목록-테이블-구성" tabindex="-1">2.1 목록 테이블 구성 <a class="header-anchor" href="#_2-1-목록-테이블-구성" aria-label="Permalink to &quot;2.1 목록 테이블 구성&quot;">​</a></h3><ul><li><strong>번호 (#)</strong>: 회의 고유 식별 번호 (ID)</li><li><strong>워크스페이스</strong>: 회의록이 소속된 워크스페이스명 (통합 회의 메뉴 조회 시 노출)</li><li><strong>상태 배지</strong>: <code>준비</code>(1), <code>종료/완료</code>(2), <code>확정</code>(3), <code>취소</code>(4) <ul><li><strong>확정 필요 경고 배지</strong>: 회의가 완료(<code>종료</code>)되었으나 회의일 기준 <strong>5일 이상 미확정</strong> 상태인 경우 경고 배지가 표시됩니다: <ul><li><em>6일 ~ 10일 경과</em>: 주황색(<code>warning</code>) 경고</li><li><em>10일 초과</em>: 빨간색(<code>danger</code>) 경고</li></ul></li></ul></li><li><strong>카테고리</strong>: 프로젝트별 회의 분류 (예: 주간미팅, 정기회의, 기술검토 등)</li><li><strong>제목</strong>: 회의 명칭 (취소 상태는 삭선 처리)</li><li><strong>회의 일시</strong>: 분 단위 일정 표시</li><li><strong>작성자 &amp; 참석자 수</strong>: 최초 등록자 및 총 참석 인원(사내+외부)</li><li><strong>PDF 다운로드</strong>: 각 행 우측의 <code>PDF 출력</code> 아이콘(<code>mdi-file-pdf-box</code>) 클릭 시 상세 이동 없이 즉시 PDF 다운로드</li></ul><h3 id="_2-2-우측-사이드바-필터링" tabindex="-1">2.2 우측 사이드바 필터링 <a class="header-anchor" href="#_2-2-우측-사이드바-필터링" aria-label="Permalink to &quot;2.2 우측 사이드바 필터링&quot;">​</a></h3><ul><li><strong>회의 일시(캘린더)</strong>, <strong>회의 상태</strong>, <strong>카테고리</strong>, **키워드 검색(제목 및 본문 통합 검색)**을 지원합니다.</li></ul><h2 id="_3-회의록-작성-및-수정-form" tabindex="-1">3. 회의록 작성 및 수정 (Form) <a class="header-anchor" href="#_3-회의록-작성-및-수정-form" aria-label="Permalink to &quot;3. 회의록 작성 및 수정 (Form)&quot;">​</a></h2><p>회의록 입력 화면은 좌측의 <strong>상세 본문 입력창</strong>과 우측의 <strong>메타 정보 설정창</strong>으로 분리되어 직관적인 입력을 지원합니다.</p><h3 id="_3-1-좌측-의사결정-자산화-본문" tabindex="-1">3.1 좌측: 의사결정 자산화 본문 <a class="header-anchor" href="#_3-1-좌측-의사결정-자산화-본문" aria-label="Permalink to &quot;3.1 좌측: 의사결정 자산화 본문&quot;">​</a></h3><ul><li><strong>회의 제목</strong>: 회의 명칭 (필수 입력)</li><li><strong>회의 의제 (Agenda)</strong>: 회의 전 사전 공유 및 논의할 핵심 안건</li><li><strong>회의 내용 (Markdown 지원)</strong>: 마크다운 에디터(<code>MdEditor</code>)를 통한 실시간 서식 편집</li><li><strong>주요 결정 사항 (Decisions)</strong>: 회의에서 최종 합의된 핵심 결정 내용 기술 (상세 보기 시 녹색 콜아웃으로 강조)</li><li><strong>후속 조치 사항 (Action Items)</strong>: 담당자별 완료 기한 및 To-Do 사항 기술 (상세 보기 시 주황색 콜아웃으로 강조)</li><li><strong>파일 첨부</strong>: 다중 파일 업로드 및 파일별 설명 입력 지원</li></ul><h3 id="_3-2-우측-메타-정보-설정" tabindex="-1">3.2 우측: 메타 정보 설정 <a class="header-anchor" href="#_3-2-우측-메타-정보-설정" aria-label="Permalink to &quot;3.2 우측: 메타 정보 설정&quot;">​</a></h3><ul><li><strong>워크스페이스</strong>: 귀속 대상 워크스페이스 지정 (필수)</li><li><strong>회의 일시</strong>: 일자 및 시간 선택 위젯(<code>DateTimePicker</code>)</li><li><strong>카테고리</strong>: 회의 분류 선택 (우측 <code>+</code> 버튼으로 모달을 띄워 즉석에서 신규 카테고리 생성 가능)</li><li><strong>상태</strong>: 진행 단계 지정 (<code>확정</code> 상태는 <code>MEETING_CONFIRM</code> 권한 보유 관리자만 선택 가능)</li><li><strong>참석자 (사내)</strong>: 사내 사용자 검색 및 멀티 칩(Chips) 다중 선택</li><li><strong>기타 참석 (외부)</strong>: 시스템 계정이 없는 외부인이나 협력사 참석자 텍스트 입력</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>신규 회의록 등록 시 유의사항</strong>: 신규 회의록 작성 중에는 회의의 식별자(PK)가 생성되지 않아 관련 업무(Issue)를 즉시 추가할 수 없습니다. 회의록 저장을 완료한 후 상세 페이지 또는 수정 모드에서 업무를 연결해 주시기 바랍니다.</p></div><h2 id="_4-회의-상세-보기-및-관련-업무-issue-연동" tabindex="-1">4. 회의 상세 보기 및 관련 업무(Issue) 연동 <a class="header-anchor" href="#_4-회의-상세-보기-및-관련-업무-issue-연동" aria-label="Permalink to &quot;4. 회의 상세 보기 및 관련 업무(Issue) 연동&quot;">​</a></h2><p>회의록 상세 페이지는 회의 결과 공유뿐만 아니라 <strong>실제 업무(Task)를 배정하고 진행 상황을 추적하는 협업 제어판</strong> 역할을 수행합니다.</p><h3 id="_4-1-권한별-수정-및-삭제-제어" tabindex="-1">4.1 권한별 수정 및 삭제 제어 <a class="header-anchor" href="#_4-1-권한별-수정-및-삭제-제어" aria-label="Permalink to &quot;4.1 권한별 수정 및 삭제 제어&quot;">​</a></h3><ul><li><strong>수정 권한</strong>: <ul><li><em>미확정 회의</em>: 관리자, 작성자, 참석자(<code>MEETING_OWN_UPDATE</code>) 수정 가능</li><li><em>확정된 회의</em>: 관리자(<code>MEETING_EDIT_CONFIRMED</code>)만 수정 가능</li></ul></li><li><strong>삭제 권한</strong>: 미확정 시 관리자/작성자, 확정 후에는 관리자(<code>MEETING_DELETE</code>)만 삭제 가능</li></ul><h3 id="_4-2-시각적-마크다운-및-콜아웃-렌더링" tabindex="-1">4.2 시각적 마크다운 및 콜아웃 렌더링 <a class="header-anchor" href="#_4-2-시각적-마크다운-및-콜아웃-렌더링" aria-label="Permalink to &quot;4.2 시각적 마크다운 및 콜아웃 렌더링&quot;">​</a></h3><ul><li>작성자/수정자 정보 및 상대 시간(경과 시간) 표시</li><li><strong>주요 결정 사항</strong>: 녹색 콜아웃(<code>Success Callout</code>)으로 시각적 강조</li><li><strong>후속 조치 사항</strong>: 주황색 콜아웃(<code>Warning Callout</code>)으로 후속 액션 리마인드</li></ul><h3 id="_4-3-관련-업무-issue-실시간-트래킹-인라인-추가" tabindex="-1">4.3 관련 업무(Issue) 실시간 트래킹 &amp; 인라인 추가 <a class="header-anchor" href="#_4-3-관련-업무-issue-실시간-트래킹-인라인-추가" aria-label="Permalink to &quot;4.3 관련 업무(Issue) 실시간 트래킹 &amp; 인라인 추가&quot;">​</a></h3><ul><li><strong>완료율 프로그레스 바</strong>: 회의와 연결된 업무들의 상태를 분석하여 **<code>완료 건수 / 전체 건수 (진행률 %)</code>**로 표시 (100% 완료 시 초록색 전환)</li><li><strong>연결 업무 테이블</strong>: 일련번호, 제목, 상태 칩, 담당자 표출 (제목 클릭 시 <a href="/work-manage/issue.html">업무 상세</a>로 즉시 이동)</li><li><strong>[관련 업무 추가] 모달</strong>: 화면 이탈 없이 회의 상세에서 즉시 신규 업무를 발행하여 회의와 자동 매핑</li></ul><h3 id="_4-4-공식-pdf-출력" tabindex="-1">4.4 공식 PDF 출력 <a class="header-anchor" href="#_4-4-공식-pdf-출력" aria-label="Permalink to &quot;4.4 공식 PDF 출력&quot;">​</a></h3><ul><li>우측 상단의 <strong>[PDF 출력]</strong> 버튼을 통해 회사 표준 양식의 회의록 PDF 문서를 다운로드하여 공식 보고 및 영구 보관용으로 활용할 수 있습니다.</li></ul><h2 id="_5-캘린더-및-활동-로그-연동" tabindex="-1">5. 캘린더 및 활동 로그 연동 <a class="header-anchor" href="#_5-캘린더-및-활동-로그-연동" aria-label="Permalink to &quot;5. 캘린더 및 활동 로그 연동&quot;">​</a></h2><ul><li><strong><a href="/work-manage/calendar.html">캘린더 연동</a></strong>: 등록된 회의 일정은 업무 캘린더에 <strong>보라색 <code>[회의]</code> 배지</strong>로 자동 표출됩니다.</li><li><strong><a href="/work-manage/activity.html">활동 기록(Activity) 연동</a></strong>: 회의 등록 및 수정 히스토리는 워크스페이스 실행 기록 피드에 실시간 로깅되어 팀원 간 진행 상황이 투명하게 공유됩니다.</li></ul>',27))])}const b=l(E,[["render",u]]);export{D as __pageData,b as default};
